pub fn copyto<T: Copy>(dst: Vec<T>, src: Vec<T>, mask: Vec<bool>) -> Vec<T> {
    // Ensure all inputs have the same length
    assert_eq!(dst.len(), src.len(), "dst and src must have the same length");
    assert_eq!(dst.len(), mask.len(), "dst and mask must have the same length");

    // For each position i, pick src[i] if mask[i] is true, otherwise dst[i].
    dst.into_iter()
       .zip(src)
       .zip(mask)
       .map(|((d, s), m)| if m { s } else { d })
       .collect()
}

